public class Main {
    static StreamTokenizer in=new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
    static int nextInt() throws IOException{
        in.nextToken();
        return (int)in.nval;
    }
    static double nextDouble() throws IOException{
        in.nextToken();
        return in.nval;
    }
    static PrintWriter out =new PrintWriter(new OutputStreamWriter(System.out));
    static int t;
    static long n,m;
    static int ans;
    //static Scanner jin=new Scanner(System.in);

    public static void main(String args[])throws IOException{
        n = nextInt();
        m = nextInt();
        if(n>m){
            long tmp = m;
            m = n;
            n =tmp;
        }
        if(n == 1){
            if(m%6==0){
                out.println(n*m);
            }
            else if(m%6==1){
                out.println(n*m-1);
            }
            else if(m%6==2){
                out.println(n*m-2);
            }
            else if(m%6==3){
                out.println(n*m-3);
            }
            else if(m%6==4){
                out.println(n*m-2);
            }
            else if(m%6==5){
                out.println(n*m-1);
            }
        }
        else if(n == 2){
