                out.println(n*m);
            }
            else if(m%2==1){
                out.println(n*m-1);
            }
        }
        else{
            if(n%2==1&&m%2==1){
                out.println(n*m-1);
            }
            else{
                out.println(n*m);
            }
        }
        out.flush();
    }
}
